#include <bits/stdc++.h>
using namespace std;

const long long MODULUS = 998244353;
const long long ROOT = 3;

long long modPow(long long base, long long exp) {
    long long result = 1;
    base %= MODULUS;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MODULUS;
        base = (base * base) % MODULUS;
        exp >>= 1;
    }
    return result;
}

void bitReversal(vector<long long>& array, int size) {
    int j = 0;
    for (int i = 1; i < size; i++) {
        int bit = size >> 1;
        while (j >= bit) {
            j -= bit;
            bit >>= 1;
        }
        j += bit;
        if (i < j) {
            swap(array[i], array[j]);
        }
    }
}

void performFFT(vector<long long>& array, int size, int direction) {
    bitReversal(array, size);
    for (int length = 2; length <= size; length <<= 1) {
        long long wlen = modPow(ROOT, (MODULUS - 1) / length);
        if (direction == -1) wlen = modPow(wlen, MODULUS - 2);
        for (int start = 0; start < size; start += length) {
            long long w = 1;
            for (int k = start; k < start + length / 2; k++) {
                long long u = array[k];
                long long v = (array[k + length / 2] * w) % MODULUS;
                array[k] = (u + v) % MODULUS;
                array[k + length / 2] = (u - v + MODULUS) % MODULUS;
                w = (w * wlen) % MODULUS;
            }
        }
    }
    if (direction == -1) {
        long long invSize = modPow(size, MODULUS - 2);
        for (int i = 0; i < size; i++) {
            array[i] = (array[i] * invSize) % MODULUS;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    int len = 1;
    int halfN = n / 2;
    while (len < (9 * halfN + 1)) len <<= 1;
    vector<long long> array(len, 0);
    for (int i = 0; i < m; i++) {
        int x;
        cin >> x;
        array[x] = 1;
    }
    performFFT(array, len, 1);
    for (int i = 0; i < len; i++) {
        if (array[i] != 0) {
            array[i] = modPow(array[i], halfN) % MODULUS;
        }
    }
    performFFT(array, len, -1);
    long long totalSum = 0;
    for (int i = 0; i < len; i++) {
        totalSum = (totalSum + (array[i] * array[i]) % MODULUS) % MODULUS;
    }
    cout << totalSum << "\n";
    return 0;
}
